-- SVU Developers Private Limited: initial PostgreSQL schema.
-- IDs and cuid references are generated by Prisma Client where declared in schema.prisma.
-- Review this migration against schema.prisma before production deployment.

CREATE TABLE "User" (
  "id" UUID NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "passwordHash" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'CUSTOMER',
  "emailVerifiedAt" TIMESTAMP(3),
  "isSuspended" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "User_role_isSuspended_idx" ON "User"("role", "isSuspended");

CREATE TABLE "Session" (
  "id" UUID NOT NULL,
  "tokenHash" TEXT NOT NULL,
  "userId" UUID NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "revokedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Session_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId", "expiresAt");

CREATE TABLE "VerificationToken" (
  "id" UUID NOT NULL,
  "tokenHash" TEXT NOT NULL,
  "purpose" TEXT NOT NULL,
  "userId" UUID NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "usedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "VerificationToken_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "VerificationToken_tokenHash_key" ON "VerificationToken"("tokenHash");
CREATE INDEX "VerificationToken_userId_purpose_expiresAt_idx" ON "VerificationToken"("userId", "purpose", "expiresAt");

CREATE TABLE "ContactEnquiry" (
  "id" UUID NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "topic" TEXT NOT NULL DEFAULT 'General',
  "message" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'NEW',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "ContactEnquiry_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "ContactEnquiry_email_createdAt_idx" ON "ContactEnquiry"("email", "createdAt");
CREATE INDEX "ContactEnquiry_status_createdAt_idx" ON "ContactEnquiry"("status", "createdAt");

CREATE TABLE "PropertyAssessment" (
  "id" UUID NOT NULL,
  "reference" TEXT NOT NULL,
  "userId" UUID,
  "assignedReviewerId" UUID,
  "propertyType" TEXT NOT NULL,
  "state" TEXT NOT NULL,
  "district" TEXT NOT NULL,
  "locality" TEXT,
  "surveyNumber" TEXT,
  "area" TEXT,
  "transactionType" TEXT,
  "email" TEXT NOT NULL,
  "phone" TEXT,
  "details" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'SUBMITTED',
  "reviewerNotes" TEXT,
  "reportNotes" TEXT,
  "completedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "PropertyAssessment_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "PropertyAssessment_reference_key" ON "PropertyAssessment"("reference");
CREATE INDEX "PropertyAssessment_status_createdAt_idx" ON "PropertyAssessment"("status", "createdAt");
CREATE INDEX "PropertyAssessment_email_createdAt_idx" ON "PropertyAssessment"("email", "createdAt");
CREATE INDEX "PropertyAssessment_userId_createdAt_idx" ON "PropertyAssessment"("userId", "createdAt");

CREATE TABLE "AssessmentCheck" (
  "id" UUID NOT NULL,
  "assessmentId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'NOT_STARTED',
  "informationReviewed" TEXT,
  "source" TEXT,
  "sourceDate" TIMESTAMP(3),
  "findings" TEXT,
  "unresolvedIssues" TEXT,
  "missingDocuments" TEXT,
  "recommendedNextSteps" TEXT,
  "reviewerId" UUID,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "AssessmentCheck_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "AssessmentCheck_assessmentId_status_idx" ON "AssessmentCheck"("assessmentId", "status");

CREATE TABLE "ServiceCatalog" (
  "id" UUID NOT NULL,
  "name" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "category" TEXT NOT NULL DEFAULT 'CONSULTATION',
  "description" TEXT NOT NULL,
  "feePaise" INTEGER NOT NULL DEFAULT 0,
  "durationMin" INTEGER NOT NULL DEFAULT 30,
  "isActive" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "ServiceCatalog_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "ServiceCatalog_slug_key" ON "ServiceCatalog"("slug");
CREATE INDEX "ServiceCatalog_isActive_category_idx" ON "ServiceCatalog"("isActive", "category");

CREATE TABLE "AvailabilitySlot" (
  "id" UUID NOT NULL,
  "startsAt" TIMESTAMP(3) NOT NULL,
  "endsAt" TIMESTAMP(3) NOT NULL,
  "serviceSlug" TEXT,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "isBooked" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AvailabilitySlot_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "AvailabilitySlot_isActive_isBooked_startsAt_idx" ON "AvailabilitySlot"("isActive", "isBooked", "startsAt");

CREATE TABLE "BookingRequest" (
  "id" UUID NOT NULL,
  "reference" TEXT NOT NULL,
  "userId" UUID,
  "service" TEXT NOT NULL,
  "serviceCatalogId" UUID,
  "slotId" UUID,
  "preferredDate" TIMESTAMP(3),
  "consultationMethod" TEXT,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "details" TEXT NOT NULL,
  "amountPaise" INTEGER NOT NULL DEFAULT 0,
  "currency" TEXT NOT NULL DEFAULT 'INR',
  "paymentStatus" TEXT NOT NULL DEFAULT 'NOT_REQUIRED',
  "status" TEXT NOT NULL DEFAULT 'REQUESTED',
  "cancellationReason" TEXT,
  "cancelledAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "BookingRequest_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "BookingRequest_reference_key" ON "BookingRequest"("reference");
CREATE UNIQUE INDEX "BookingRequest_slotId_key" ON "BookingRequest"("slotId");
CREATE INDEX "BookingRequest_status_preferredDate_idx" ON "BookingRequest"("status", "preferredDate");
CREATE INDEX "BookingRequest_email_createdAt_idx" ON "BookingRequest"("email", "createdAt");
CREATE INDEX "BookingRequest_userId_createdAt_idx" ON "BookingRequest"("userId", "createdAt");

CREATE TABLE "DisputeCase" (
  "id" UUID NOT NULL,
  "reference" TEXT NOT NULL,
  "userId" UUID,
  "assignedReviewerId" UUID,
