  "statement" TEXT NOT NULL,
  "reliefSought" TEXT,
  "agreementDetails" TEXT,
  "status" TEXT NOT NULL DEFAULT 'SUBMITTED',
  "feePaise" INTEGER NOT NULL DEFAULT 0,
  "paymentStatus" TEXT NOT NULL DEFAULT 'NOT_REQUIRED',
  "reviewerNotes" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "DisputeCase_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "DisputeCase_reference_key" ON "DisputeCase"("reference");
CREATE INDEX "DisputeCase_status_createdAt_idx" ON "DisputeCase"("status", "createdAt");
CREATE INDEX "DisputeCase_email_createdAt_idx" ON "DisputeCase"("email", "createdAt");
CREATE INDEX "DisputeCase_userId_createdAt_idx" ON "DisputeCase"("userId", "createdAt");
CREATE INDEX "DisputeCase_assignedReviewerId_status_idx" ON "DisputeCase"("assignedReviewerId", "status");

CREATE TABLE "CaseStatusEvent" (
  "id" UUID NOT NULL,
  "disputeCaseId" UUID NOT NULL,
  "fromStatus" TEXT,
  "toStatus" TEXT NOT NULL,
  "actorId" UUID,
  "note" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CaseStatusEvent_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "CaseStatusEvent_disputeCaseId_createdAt_idx" ON "CaseStatusEvent"("disputeCaseId", "createdAt");
CREATE INDEX "CaseStatusEvent_actorId_createdAt_idx" ON "CaseStatusEvent"("actorId", "createdAt");

CREATE TABLE "CaseMilestone" (
  "id" UUID NOT NULL,
  "disputeCaseId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT,
  "dueAt" TIMESTAMP(3),
  "completedAt" TIMESTAMP(3),
  "status" TEXT NOT NULL DEFAULT 'PLANNED',
  "createdById" UUID,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "CaseMilestone_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "CaseMilestone_disputeCaseId_status_dueAt_idx" ON "CaseMilestone"("disputeCaseId", "status", "dueAt");
CREATE INDEX "CaseMilestone_createdById_createdAt_idx" ON "CaseMilestone"("createdById", "createdAt");

CREATE TABLE "Document" (
  "id" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "assessmentId" UUID,
  "disputeCaseId" UUID,
  "bookingId" UUID,
  "originalName" TEXT NOT NULL,
  "storedName" TEXT NOT NULL,
  "mimeType" TEXT NOT NULL,
  "sizeBytes" INTEGER NOT NULL,
  "sha256" TEXT NOT NULL,
  "accessLevel" TEXT NOT NULL DEFAULT 'OWNER_AND_ASSIGNED_STAFF',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deletedAt" TIMESTAMP(3),
  CONSTRAINT "Document_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Document_storedName_key" ON "Document"("storedName");
CREATE INDEX "Document_userId_createdAt_idx" ON "Document"("userId", "createdAt");
CREATE INDEX "Document_assessmentId_idx" ON "Document"("assessmentId");
CREATE INDEX "Document_disputeCaseId_idx" ON "Document"("disputeCaseId");

CREATE TABLE "CaseMessage" (
  "id" UUID NOT NULL,
