CREATE TABLE "Payment" (
  "id" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "activeTargetKey" TEXT,
  "bookingId" UUID,
  "disputeCaseId" UUID,
  "amountPaise" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'INR',
  "status" TEXT NOT NULL DEFAULT 'CREATED',
  "gateway" TEXT NOT NULL DEFAULT 'RAZORPAY',
  "gatewayOrderId" TEXT,
  "gatewayPaymentId" TEXT,
  "signatureVerifiedAt" TIMESTAMP(3),
  "idempotencyKey" TEXT NOT NULL,
  "failureReason" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "Payment_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Payment_activeTargetKey_key" ON "Payment"("activeTargetKey");
CREATE UNIQUE INDEX "Payment_gatewayOrderId_key" ON "Payment"("gatewayOrderId");
CREATE UNIQUE INDEX "Payment_gatewayPaymentId_key" ON "Payment"("gatewayPaymentId");
CREATE UNIQUE INDEX "Payment_idempotencyKey_key" ON "Payment"("idempotencyKey");
CREATE INDEX "Payment_userId_status_createdAt_idx" ON "Payment"("userId", "status", "createdAt");
CREATE INDEX "Payment_bookingId_status_idx" ON "Payment"("bookingId", "status");

